<?php namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\ValidationException;
class AuthController extends Controller { public function register(Request $r){$d=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:users','phone'=>'nullable|string|max:30','password'=>'required|string|min:8|confirmed']);$u=User::create($d);return response()->json(['user'=>$u,'token'=>$u->createToken('web')->plainTextToken],201);} public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required']);$u=User::where('email',$d['email'])->first();if(!$u||!Hash::check($d['password'],$u->password))throw ValidationException::withMessages(['email'=>'اطلاعات ورود صحیح نیست.']);return ['user'=>$u,'token'=>$u->createToken('web')->plainTextToken];} public function logout(Request $r){$r->user()->currentAccessToken()?->delete();return ['message'=>'خارج شدید.'];} public function me(Request $r){return $r->user();} }
